/*-----------------------------------------------------------------------------------*/
/*                         寄存器配置 (来自慷炜电子)                                   */
/*-----------------------------------------------------------------------------------*/

// 注意：这些是用于初始化的固定值，函数内部会根据模式动态修改CFR1
const u8 init_CFR1[] = {0x00, 0x40, 0x00, 0x00};
const u8 init_CFR2[] = {0x01, 0x00, 0x00, 0x00};
const u8 init_CFR3[] = {0x05, 0x0F, 0x41, 0x32};

/*-----------------------------------------------------------------------------------*/
/*                              内部(私有)函数                                       */
/*-----------------------------------------------------------------------------------*/

// 8位串行发送
static void txd_8bit(u8 txdat) {
    u8 i;
    for (i = 0; i < 8; i++) {
        HAL_GPIO_WritePin(AD9910_SCLK_GPIO_Port, AD9910_SCLK_Pin, GPIO_PIN_RESET);
        if (txdat & 0x80) HAL_GPIO_WritePin(AD9910_SDIO_GPIO_Port, AD9910_SDIO_Pin, GPIO_PIN_SET);
        else HAL_GPIO_WritePin(AD9910_SDIO_GPIO_Port, AD9910_SDIO_Pin, GPIO_PIN_RESET);
        HAL_GPIO_WritePin(AD9910_SCLK_GPIO_Port, AD9910_SCLK_Pin, GPIO_PIN_SET);
        txdat <<= 1;
    }
    HAL_GPIO_WritePin(AD9910_SCLK_GPIO_Port, AD9910_SCLK_Pin, GPIO_PIN_RESET);
}

// 32位串行发送 (AWG模式需要)
static void write_32bit(u32 dat) {
    u8 i;
    u32 com = 0x80000000;
    for(i=0; i < 32; i++) {
        HAL_GPIO_WritePin(AD9910_SCLK_GPIO_Port, AD9910_SCLK_Pin, GPIO_PIN_RESET);
        if((dat & com) == 0) HAL_GPIO_WritePin(AD9910_SDIO_GPIO_Port, AD9910_SDIO_Pin, GPIO_PIN_RESET);
        else HAL_GPIO_WritePin(AD9910_SDIO_GPIO_Port, AD9910_SDIO_Pin, GPIO_PIN_SET);
        HAL_GPIO_WritePin(AD9910_SCLK_GPIO_Port, AD9910_SCLK_Pin, GPIO_PIN_SET);
        com = com >> 1;
    }
    HAL_GPIO_WritePin(AD9910_SCLK_GPIO_Port, AD9910_SCLK_Pin, GPIO_PIN_RESET);
}

// 寄存器写操作的封装
static void write_reg(u8 reg_addr, const u8* data, u8 len) {
    u8 i;
    HAL_GPIO_WritePin(AD9910_CS_GPIO_Port, AD9910_CS_Pin, GPIO_PIN_RESET);
    txd_8bit(reg_addr);
    for (i = 0; i < len; i++) txd_8bit(data[i]);
    HAL_GPIO_WritePin(AD9910_CS_GPIO_Port, AD9910_CS_Pin, GPIO_PIN_SET);
}

// I/O Update脉冲
static void io_update(void) {
    HAL_GPIO_WritePin(AD9910_UPDATE_GPIO_Port, AD9910_UPDATE_Pin, GPIO_PIN_SET);
    __NOP();__NOP();__NOP();__NOP();__NOP(); 
    HAL_GPIO_WritePin(AD9910_UPDATE_GPIO_Port, AD9910_UPDATE_Pin, GPIO_PIN_RESET);
}

/*-----------------------------------------------------------------------------------*/
/*                              公有API函数实现                                        */
/*-----------------------------------------------------------------------------------*/

void Init_AD9910(void) {
    // 硬件复位
    HAL_GPIO_WritePin(AD9910_RESET_GPIO_Port, AD9910_RESET_Pin, GPIO_PIN_SET); HAL_Delay(5);
    HAL_GPIO_WritePin(AD9910_RESET_GPIO_Port, AD9910_RESET_Pin, GPIO_PIN_RESET); HAL_Delay(1);
    
    // 初始化控制引脚
    HAL_GPIO_WritePin(AD9910_PROFILE0_GPIO_Port, AD9910_PROFILE0_Pin, GPIO_PIN_RESET);
    HAL_GPIO_WritePin(AD9910_PROFILE1_GPIO_Port, AD9910_PROFILE1_Pin, GPIO_PIN_RESET);
    HAL_GPIO_WritePin(AD9910_PROFILE2_GPIO_Port, AD9910_PROFILE2_Pin, GPIO_PIN_RESET);
    HAL_GPIO_WritePin(AD9910_DRCTL_GPIO_Port, AD9910_DRCTL_Pin, GPIO_PIN_RESET);
    HAL_GPIO_WritePin(AD9910_DRHOLD_GPIO_Port, AD9910_DRHOLD_Pin, GPIO_PIN_RESET);

    // 写入初始寄存器配置
    write_reg(0x00, init_CFR1, 4); HAL_Delay(1);
    write_reg(0x01, init_CFR2, 4); HAL_Delay(1);
    write_reg(0x02, init_CFR3, 4); HAL_Delay(1);
    
    io_update();
}

void AD9910_RAM_WAVE_Set(AD9910_Wave_t wave) {
    int i;
    const u32 *srcWaveData;
    
    // 【第1步】配置CFR1，设定RAM数据目标为幅度，并开启反Sinc滤波
    u8 CFR1_AWG_Setup[] = {0x40, 0x40, 0x00, 0x00};
    write_reg(0x00, CFR1_AWG_Setup, 4);

    // 【第2步】配置RAM Profile 0，设定播放参数
    // 输出频率 = 1GHz / (4 * M) / 1024, M = 地址步进率
    u8 RAM_Profile0[] = {0x00, 0x01, 0x03, 0xff, 0x00, 0x00, 0x00, 0x04};
    // M=1, StartAddr=0, EndAddr=1023(0x3FF), Mode=0x04(连续循环)
    write_reg(0x0E, RAM_Profile0, 8);

    // 【第3步】第一次I/O Update，锁存以上配置
    io_update();

    // 【第4步】选择波形数据并写入RAM
    HAL_GPIO_WritePin(AD9910_CS_GPIO_Port, AD9910_CS_Pin, GPIO_PIN_RESET);
    txd_8bit(0x16); // RAM 写指令
    
    switch(wave) {
        case TRIG_WAVE:   srcWaveData = RAM_TRIG_WAVE; break;
        case SQUARE_WAVE: srcWaveData = RAM_SQUARE_WAVE; break;
        case SINC_WAVE:   srcWaveData = RAM_SINC_WAVE; break;
        default:          srcWaveData = RAM_TRIG_WAVE; break;
    }
    
    for(i = 0; i < 1024; i++) {
        // 【关键】将14位数据左移18位，写入32位RAM字
        write_32bit(srcWaveData[i] << 18);
    }
    HAL_GPIO_WritePin(AD9910_CS_GPIO_Port, AD9910_CS_Pin, GPIO_PIN_SET);

    // 【第5步】再次配置CFR1，这次将RAM使能位置1
    CFR1_AWG_Setup[0] |= 0x80; // RAM Enable (CFR1[31]=1)
    write_reg(0x00, CFR1_AWG_Setup, 4);

    // 【第6步】最终的I/O Update，启动播放
    io_update();
}